// n8n Code node: "Normalize Lead"  (mode: Run Once for All Items)
// Maps leads from DEMO · Load Sample Leads or Webhook · Receive Lead to one canonical schema.
// - Lead content is UNTRUSTED input: control characters are stripped, the message is length-capped,
//   and prompt-injection / markup / spam patterns are flagged (never executed or obeyed).
// - The original payload is preserved in raw_input (webhook headers are NOT kept: they may carry secrets).

const MAX_MESSAGE_CHARS = 4000;

const FREE_EMAIL_DOMAINS = ['gmail.com', 'googlemail.com', 'yahoo.com', 'outlook.com', 'hotmail.com', 'live.com', 'icloud.com', 'aol.com', 'proton.me', 'protonmail.com', 'gmx.com', 'gmx.de', 'web.de', 'mail.com'];
const DISPOSABLE_EMAIL_DOMAINS = ['mailinator.com', 'guerrillamail.com', '10minutemail.com', 'tempmail.com', 'temp-mail.org', 'yopmail.com', 'trashmail.com', 'sharklasers.com', 'getnada.com'];

const INJECTION_PATTERNS = [
  /ignore\s+(all\s+|any\s+)?(the\s+)?(previous|prior|above|earlier)\s+(instructions|prompts?|rules)/i,
  /(reveal|show|print|output|include|leak)\b.{0,40}\b(system\s*prompt|api[\s_-]*keys?|credentials?|secrets?|passwords?)/i,
  /\byou\s+are\s+now\b|\bact\s+as\s+(an?|the)\s+/i,
  /\b(classify|mark|score|rate|label)\s+(this|me|my|the)\s+(lead|inquiry|request)?.{0,30}\b(hot|100)\b/i,
  /\b(system|assistant)\s*:\s/i,
];
const MARKUP_PATTERN = /<\s*\/?\s*(script|iframe|object|embed|img|svg|a)\b|javascript:|on\w+\s*=/i;

const SPAM_KEYWORDS = [/guarantee/i, /backlinks?/i, /#\s?1\s+(rank|on google)/i, /ranking on google/i, /\bseo\b/i, /crypto|bitcoin/i, /casino|betting/i, /\bloans?\b/i, /limited (time )?offer/i, /act now/i, /dear sir\s*\/?\s*madam/i, /click here/i, /100% free/i, /cheap/i];

// ---------- helpers ----------
const clean = (v) => {
  if (v === null || v === undefined) return '';
  return String(v)
    .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
};

const pick = (obj, keys) => {
  for (const k of keys) {
    const v = clean(obj[k]);
    if (v) return v;
  }
  return '';
};

function parseBudget(text) {
  const t = clean(text).toLowerCase().replace(/,/g, '');
  if (!t) return { min: null, max: null, currency: null, estimate: null };
  const currency = /€|\beur\b/.test(t) ? 'EUR' : /£|\bgbp\b/.test(t) ? 'GBP' : /\$|\busd\b/.test(t) ? 'USD' : null;
  const nums = [...t.matchAll(/(\d+(?:\.\d+)?)\s*(k|m)?\b/g)].map((m) => parseFloat(m[1]) * (m[2] === 'k' ? 1e3 : m[2] === 'm' ? 1e6 : 1));
  if (!nums.length) return { min: null, max: null, currency, estimate: null };
  if (/under|less than|below|<|up to|max/.test(t)) return { min: 0, max: nums[0], currency, estimate: nums[0] };
  const min = nums[0];
  const max = nums[1] !== undefined ? nums[1] : nums[0];
  return { min, max, currency, estimate: min }; // conservative: use the lower bound
}

function parseTimelineDays(text) {
  const t = clean(text).toLowerCase();
  if (!t) return null;
  if (/asap|immediately|urgent|this week|right away/.test(t)) return 7;
  if (/no rush|no specific|not sure|someday|next year|no timeline|eventually|at some point/.test(t)) return 365;
  const m = t.match(/(\d+)\s*(?:-|–|to)?\s*(\d+)?\s*(day|week|month)/);
  if (m) {
    const n = parseInt(m[2] || m[1], 10);
    return n * (m[3] === 'day' ? 1 : m[3] === 'week' ? 7 : 30);
  }
  if (/this month/.test(t)) return 30;
  if (/this quarter/.test(t)) return 90;
  if (/next quarter|this year/.test(t)) return 180;
  return null;
}

function parseCompanySize(text) {
  const t = clean(text).replace(/,/g, '');
  const nums = (t.match(/\d+/g) || []).map(Number);
  if (!nums.length) return { min: null, max: null };
  if (/\+|over|more than/i.test(t)) return { min: nums[0], max: null };
  return { min: nums[0], max: nums[1] !== undefined ? nums[1] : nums[0] };
}

const toDomain = (url) => clean(url).toLowerCase().replace(/^[a-z]+:\/\//, '').replace(/^www\./, '').split(/[/?#]/)[0] || '';

// ---------- main ----------
const out = [];
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const j = items[i].json || {};

  // Webhook items look like { headers, params, query, body, webhookUrl, executionMode }
  const isWebhook = j.body !== undefined && j.headers !== undefined;
  let payload = isWebhook ? j.body : j;
  if (typeof payload === 'string') {
    try { payload = JSON.parse(payload); } catch (e) { payload = { message: payload }; }
  }
  if (!payload || typeof payload !== 'object' || Array.isArray(payload)) payload = {};

  const firstLast = [pick(payload, ['first_name', 'firstName']), pick(payload, ['last_name', 'lastName'])].filter(Boolean).join(' ');
  const full_name = pick(payload, ['full_name', 'fullName', 'name', 'contact_name']) || firstLast;
  const nameParts = full_name.split(' ').filter(Boolean);

  const email = pick(payload, ['email', 'email_address', 'emailAddress', 'work_email']).toLowerCase();
  const email_valid = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email);
  const email_domain = email_valid ? email.split('@')[1] : '';

  const phone = pick(payload, ['phone', 'phone_number', 'phoneNumber', 'mobile']);
  const phoneDigits = phone.replace(/[^\d]/g, '');
  const phone_normalized = phoneDigits ? (phone.trim().startsWith('+') ? '+' : '') + phoneDigits : '';

  let message = pick(payload, ['message', 'comments', 'comment', 'notes', 'inquiry', 'description']);
  const message_truncated = message.length > MAX_MESSAGE_CHARS;
  if (message_truncated) message = message.slice(0, MAX_MESSAGE_CHARS);
  const message_clean = message.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();

  const company = pick(payload, ['company', 'company_name', 'companyName', 'organization', 'organisation']);
  const website = pick(payload, ['website', 'url', 'company_website', 'domain']);
  const estimated_budget = pick(payload, ['estimated_budget', 'budget', 'estimatedBudget']);
  const timeline = pick(payload, ['timeline', 'timeframe', 'time_frame']);
  const company_size = pick(payload, ['company_size', 'companySize', 'employees', 'team_size']);
  const budget = parseBudget(estimated_budget);
  const size = parseCompanySize(company_size);

  const tsRaw = pick(payload, ['timestamp', 'submitted_at', 'created_at', 'date']);
  const tsParsed = tsRaw ? new Date(tsRaw) : null;
  const receivedAt = new Date().toISOString();

  const lead = {
    lead_id: pick(payload, ['lead_id', 'leadId', 'id']) || `L-${Date.now().toString(36).toUpperCase()}-${i + 1}`,
    timestamp: tsParsed && !isNaN(tsParsed) ? tsParsed.toISOString() : receivedAt,
    full_name,
    first_name: nameParts[0] || '',
    last_name: nameParts.slice(1).join(' '),
    email,
    email_valid,
    email_domain,
    free_email_provider: FREE_EMAIL_DOMAINS.includes(email_domain),
    phone,
    phone_normalized,
    phone_valid: phoneDigits.length >= 7,
    company,
    job_title: pick(payload, ['job_title', 'jobTitle', 'title', 'role', 'position']),
    company_size,
    company_size_min: size.min,
    company_size_max: size.max,
    industry: pick(payload, ['industry', 'sector']),
    source: pick(payload, ['source', 'lead_source', 'utm_source']) || (isWebhook ? 'Webhook' : 'Unknown'),
    country: pick(payload, ['country', 'country_name']),
    message: message_clean,
    estimated_budget,
    budget_min: budget.min,
    budget_max: budget.max,
    budget_currency: budget.currency,
    budget_estimate: budget.estimate,
    timeline,
    timeline_days: parseTimelineDays(timeline),
    requested_service: pick(payload, ['requested_service', 'service', 'requestedService', 'interest']),
    website,
    website_domain: toDomain(website),
  };

  // ---------- validation ----------
  const missing_required = [];
  if (!lead.full_name) missing_required.push('full_name');
  if (!lead.email_valid) missing_required.push(lead.email ? 'email (invalid)' : 'email');
  if (!lead.company) missing_required.push('company');
  if (lead.message.length < 10) missing_required.push('message');
  const OPTIONAL = ['phone', 'job_title', 'company_size', 'industry', 'estimated_budget', 'timeline', 'requested_service', 'website', 'country'];
  const missing_optional = OPTIONAL.filter((k) => !lead[k]);

  // ---------- security (untrusted input) ----------
  const scanText = [message, lead.requested_service, lead.full_name, lead.company, lead.job_title].join(' \n ');
  const prompt_injection_suspected = INJECTION_PATTERNS.some((re) => re.test(scanText));
  const markup_detected = MARKUP_PATTERN.test(scanText);
  const urlCount = (message.match(/https?:\/\/|www\./gi) || []).length;
  const securityFlags = [];
  if (prompt_injection_suspected) securityFlags.push('prompt_injection_suspected');
  if (markup_detected) securityFlags.push('html_or_script_markup');
  if (message_truncated) securityFlags.push('message_truncated');

  // ---------- deterministic spam signals (used by both demo and production paths) ----------
  const spamSignals = [];
  const kwHits = SPAM_KEYWORDS.filter((re) => re.test(message + ' ' + lead.requested_service)).length;
  if (kwHits) spamSignals.push(`spam_keywords:${kwHits}`);
  if (urlCount >= 2) spamSignals.push(`links_in_message:${urlCount}`);
  const exclamations = (message.match(/!/g) || []).length;
  if (exclamations >= 3) spamSignals.push(`exclamation_marks:${exclamations}`);
  const letters = message.replace(/[^A-Za-z]/g, '');
  const capsRatio = letters.length ? letters.replace(/[^A-Z]/g, '').length / letters.length : 0;
  if (letters.length > 20 && capsRatio > 0.3) spamSignals.push('excessive_caps');
  if (DISPOSABLE_EMAIL_DOMAINS.includes(email_domain)) spamSignals.push('disposable_email_domain');
  const spamScore = Math.min(kwHits, 3) + (urlCount >= 2 ? 1 : 0) + (exclamations >= 3 ? 1 : 0) + (letters.length > 20 && capsRatio > 0.3 ? 1 : 0) + (DISPOSABLE_EMAIL_DOMAINS.includes(email_domain) ? 2 : 0);

  out.push({
    json: {
      ...lead,
      validation: {
        is_complete: missing_required.length === 0,
        missing_required,
        missing_optional,
        missing_fields: [...missing_required, ...missing_optional],
      },
      security: {
        prompt_injection_suspected,
        markup_detected,
        message_truncated,
        flags: securityFlags,
        risk_level: prompt_injection_suspected || markup_detected ? 'high' : 'low',
      },
      spam_check: {
        spam_score: spamScore,
        signals: spamSignals,
        likely_spam: spamScore >= 3,
      },
      _meta: {
        entry_channel: isWebhook ? 'webhook' : 'demo',
        batch_index: i,
        received_at: receivedAt,
        normalizer_version: '1.0',
      },
      raw_input: JSON.parse(JSON.stringify(payload)),
    },
    pairedItem: { item: i },
  });
}

return out;

// n8n Code node: "Check Duplicate"  (mode: Run Once for All Items)
// Deterministic duplicate detection:
//   1. same email address                        -> DUPLICATE
//   2. same company (normalized) + same last name -> DUPLICATE
//   3. same company / business domain only        -> not a duplicate, flagged as related_account
// Leads are compared with earlier leads in the same batch. In production (demo_mode = false) the
// workflow's static data also remembers leads from previous executions (active workflows only).
// For a real CRM, replace/extend this with a CRM search (e.g. HubSpot "search contacts by email").

const items = $input.all();
const demoMode = items.length ? items[0].json.config?.demo_mode !== false : true;
const MAX_REMEMBERED = 5000;

let memory = null;
if (!demoMode) {
  const store = $getWorkflowStaticData('global');
  store.seenLeads = store.seenLeads || {};
  memory = store.seenLeads;
}

const normCompany = (s) => (s || '').toLowerCase()
  .replace(/\b(ltd|limited|inc|llc|gmbh|co|corp|corporation|plc|ag|sa|bv|group|holdings?)\b\.?/g, '')
  .replace(/[^a-z0-9]/g, '');

const batch = {};
const lookup = (key) => batch[key] || (memory ? memory[key] : undefined);
const remember = (key, value) => {
  batch[key] = value;
  if (memory) memory[key] = value;
};

const out = items.map((item, i) => {
  const lead = item.json;
  const emailKey = lead.email_valid ? `email:${lead.email}` : null;
  const company = normCompany(lead.company);
  const companyNameKey = company && lead.last_name ? `company_name:${company}|${lead.last_name.toLowerCase()}` : null;
  const businessDomain = lead.website_domain || (!lead.free_email_provider ? lead.email_domain : '');
  const accountKeys = [company ? `company:${company}` : null, businessDomain ? `domain:${businessDomain}` : null].filter(Boolean);

  let duplicate_of = null;
  let match_type = null;
  if (emailKey && lookup(emailKey)) {
    duplicate_of = lookup(emailKey).lead_id;
    match_type = 'same_email';
  } else if (companyNameKey && lookup(companyNameKey)) {
    duplicate_of = lookup(companyNameKey).lead_id;
    match_type = 'same_company_and_last_name';
  }

  let related_account = null;
  if (!duplicate_of) {
    const hit = accountKeys.map(lookup).find(Boolean);
    if (hit) related_account = hit.lead_id;
  }

  // Only register originals, so every duplicate points at the first record.
  if (!duplicate_of) {
    const ref = { lead_id: lead.lead_id, first_seen: lead.timestamp };
    [emailKey, companyNameKey, ...accountKeys].filter(Boolean).forEach((k) => { if (!lookup(k)) remember(k, ref); });
  }

  return {
    json: {
      ...lead,
      duplicate_check: {
        is_duplicate: Boolean(duplicate_of),
        duplicate_of,
        match_type,
        related_account,
        checked_against: memory ? 'batch + workflow memory' : 'current batch',
      },
    },
    pairedItem: { item: i },
  };
});

// Keep workflow memory bounded.
if (memory) {
  const keys = Object.keys(memory);
  if (keys.length > MAX_REMEMBERED) keys.slice(0, keys.length - MAX_REMEMBERED).forEach((k) => delete memory[k]);
}

return out;

// n8n Code node: "DEMO · Mock Lead Analysis"  (mode: Run Once for All Items)
// DEMO MODE ONLY. Produces an AI-style structured analysis with deterministic heuristics.
// No external API is called. The output has exactly the same shape the production AI path
// must return (see prompts/lead-analysis.md), so everything downstream is identical.

const MODEL = 'mock-analyzer-v1';

const NEED_TERMS = [
  ['manual process', /manual|by hand|copy(ing|ied)?\b.{0,20}\b(paste|manually)|copied manually/i],
  ['spreadsheet tracking', /spreadsheet|excel|google sheets?/i],
  ['CRM', /\bcrm\b|salesforce|hubspot|pipedrive|zoho/i],
  ['qualification', /qualif/i],
  ['routing', /\brout(e|es|ing)\b|assign(ment)?/i],
  ['response time', /response time|respond faster|slow to respond|more than a day/i],
  ['consolidation', /consolidat|multiple (teams|tools|systems)|regional/i],
  ['integration', /integrat/i],
  ['automation', /automat/i],
  ['AI assistant', /chatbot|\bai assistant\b|assistant|support bot/i],
  ['scale', /\bscal(e|ing)\b|growing|volume/i],
];
const COMMITMENT = /\bwe need\b|\bmust\b|approved|priority|go live|deadline|\basap\b|this week/i;
const EXPLORATORY = /exploring|just looking|looking around|researching|not sure|\bmaybe\b|\bmight\b|down the line|at some point|curious/i;
const EXPLICIT_ASK = /\b(call|meeting|schedule|demo|proposal|quote|scope)\b/i;

const PAIN_POINTS = [
  [/manual|copied manually|by hand/i, 'inbound leads are currently handled manually'],
  [/spreadsheet|excel/i, 'leads are tracked in spreadsheets before reaching the CRM'],
  [/response time|more than a day|slow/i, 'response times to new inquiries are too slow'],
  [/consolidat|regional|multiple (teams|tools)/i, 'lead intake is spread across several teams or tools'],
  [/los(e|ing) leads|fall through|slip/i, 'leads are slipping through the cracks'],
  [/scal(e|ing)|growing/i, 'the current process does not scale with growth'],
  [/customer portal|support/i, 'customer questions need faster answers'],
];

const DECISION_MAKER = /\b(ceo|cto|coo|cfo|cmo|cro|cio|founder|co-?founder|owner|president|vp|vice president|head of|director|partner|managing director)\b/i;
const INFLUENCER = /\b(manager|lead|senior|principal|architect)\b/i;
const INDIVIDUAL = /\b(coordinator|assistant|associate|intern|analyst|specialist|representative)\b/i;

const SERVICE_CORE = /lead (qualification|routing|scoring|management)|\bcrm\b|hubspot|salesforce|pipedrive|qualif|routing/i;
const SERVICE_SECONDARY = /automat|workflow|integrat|chatbot|assistant|\bn8n\b|\bai\b/i;

const RUBRIC = {
  budget_fit: { strong: 20, moderate: 12, weak: 5, very_low: 0, unknown: 0 },
  authority_level: { decision_maker: 20, influencer: 12, individual: 5, unknown: 0 },
  business_need: { strong: 20, moderate: 12, weak: 4 },
  urgency: { high: 15, medium: 9, low: 3, unknown: 0 },
  service_fit: { strong: 15, partial: 8, none: 0 },
  company_fit: { strong: 10, moderate: 6, weak: 2 },
};

const round2 = (n) => Math.round(n * 100) / 100;

return $input.all().map((item, i) => {
  const lead = item.json;
  const cfg = lead.config || {};
  const text = `${lead.message} ${lead.requested_service}`;

  // --- business need & intent ---
  const needMatches = NEED_TERMS.filter(([, re]) => re.test(text)).map(([label]) => label);
  const committed = COMMITMENT.test(lead.message);
  const exploratory = EXPLORATORY.test(lead.message);
  const asks = EXPLICIT_ASK.test(lead.message);
  let business_need = 'weak';
  if (needMatches.length >= 4 && committed) business_need = 'strong';
  else if (needMatches.length >= 2) business_need = 'moderate';

  let buying_intent = 'low';
  if (lead.message.length < 25 || (needMatches.length === 0 && !lead.requested_service)) buying_intent = 'unclear';
  else if (business_need !== 'weak' && committed && asks) buying_intent = 'high';
  else if (business_need !== 'weak') buying_intent = 'medium';
  if (lead.spam_check.likely_spam) buying_intent = 'unclear';

  // --- authority ---
  const title = lead.job_title || '';
  const authority_level = !title ? 'unknown' : DECISION_MAKER.test(title) ? 'decision_maker' : INFLUENCER.test(title) ? 'influencer' : INDIVIDUAL.test(title) ? 'individual' : 'unknown';

  // --- budget ---
  const b = lead.budget_estimate;
  const budget_fit = b === null || b === undefined ? 'unknown' : b >= 20000 ? 'strong' : b >= 5000 ? 'moderate' : b >= 1000 ? 'weak' : b > 0 ? 'very_low' : 'unknown';

  // --- urgency ---
  const d = lead.timeline_days;
  let urgency = d === null || d === undefined ? 'unknown' : d <= 30 ? 'high' : d <= 90 ? 'medium' : 'low';
  if (urgency === 'unknown' && /\basap\b|urgent|this week/i.test(lead.message)) urgency = 'high';

  // --- fit ---
  const service_fit = SERVICE_CORE.test(text) ? 'strong' : SERVICE_SECONDARY.test(text) ? 'partial' : 'none';
  const targetIndustries = (cfg.target_industries || []).map((s) => s.toLowerCase());
  const inTarget = Boolean(lead.industry) && targetIndustries.some((t) => lead.industry.toLowerCase().includes(t));
  const ideal = cfg.ideal_company_size || { min: 50, max: 1000 };
  const sizeFit = lead.company_size_min !== null && lead.company_size_min >= ideal.min && (lead.company_size_max ?? lead.company_size_min) <= ideal.max;
  const company_fit = inTarget && sizeFit ? 'strong' : inTarget || sizeFit ? 'moderate' : 'weak';
  const business_fit = service_fit === 'strong' && company_fit !== 'weak' ? 'strong' : service_fit !== 'none' ? 'moderate' : 'weak';

  // --- flags ---
  const spam = lead.spam_check.likely_spam;
  const duplicate = lead.duplicate_check.is_duplicate;
  const prompt_injection_detected = lead.security.prompt_injection_suspected;
  const missing_fields = lead.validation.missing_fields;

  // --- "AI" suggestion (the rules in Score Lead make the final call) ---
  const rubric = RUBRIC.budget_fit[budget_fit] + RUBRIC.authority_level[authority_level] + RUBRIC.business_need[business_need]
    + RUBRIC.urgency[urgency] + RUBRIC.service_fit[service_fit] + RUBRIC.company_fit[company_fit];
  let suggested = Math.round(rubric * 0.95) + (asks && committed ? 3 : 0) - (exploratory ? 5 : 0);
  if (spam) suggested = Math.min(suggested, 5);
  if (prompt_injection_detected) suggested = Math.min(suggested, 20);
  suggested = Math.max(0, Math.min(100, suggested));
  const temp = suggested >= 80 ? 'HOT' : suggested >= 55 ? 'WARM' : suggested >= 30 ? 'COLD' : 'REJECT';

  let lead_category = temp;
  if (spam) lead_category = 'SPAM';
  else if (prompt_injection_detected || !lead.validation.is_complete) lead_category = 'NEEDS_REVIEW';
  else if (duplicate) lead_category = 'DUPLICATE';

  const qualification_status = {
    HOT: 'QUALIFIED', WARM: 'QUALIFIED', COLD: 'NURTURE', REJECT: 'REJECTED', SPAM: 'REJECTED', DUPLICATE: 'DUPLICATE',
    NEEDS_REVIEW: lead.validation.is_complete ? 'NEEDS_REVIEW' : 'INCOMPLETE',
  }[lead_category];

  const recommended_action = {
    HOT: 'Contact within 30 minutes and offer a discovery call.',
    WARM: 'Send a personal follow-up today with 2-3 scoping questions.',
    COLD: 'Add to the nurture sequence and re-score on engagement.',
    REJECT: 'Archive; low fit and low intent.',
    SPAM: 'Archive as spam. Do not reply.',
    DUPLICATE: `Merge into existing record ${lead.duplicate_check.duplicate_of} and notify its owner.`,
    NEEDS_REVIEW: prompt_injection_detected
      ? 'Manual review: the message contains instructions aimed at the AI system.'
      : `Manual review: missing ${lead.validation.missing_required.join(', ') || 'key information'}.`,
  }[lead_category];

  // --- pain points (plain-language, used in follow-up drafts) ---
  const pain_points = PAIN_POINTS.filter(([re]) => re.test(lead.message)).map(([, p]) => p).slice(0, 3);

  // --- summary (built only from facts in the lead) ---
  const who = `${title || 'Contact'} at ${lead.company || 'an unknown company'}`
    + (lead.company_size || lead.industry ? ` (${[lead.company_size && `${lead.company_size} employees`, lead.industry].filter(Boolean).join(', ')})` : '');
  const parts = [`${who}.`];
  if (spam) parts.push(`Message shows typical spam patterns (${lead.spam_check.signals.join(', ')}).`);
  else {
    if (business_need === 'strong') parts.push(`Clear, specific need: ${pain_points.join('; ') || needMatches.join(', ')}.`);
    else if (business_need === 'moderate') parts.push(`Genuine use case (${pain_points[0] || needMatches.slice(0, 3).join(', ')})${exploratory ? ', still exploring options' : ''}.`);
    else parts.push('Need is vague or not yet defined.');
    parts.push(lead.estimated_budget ? `Budget: ${lead.estimated_budget} (${budget_fit.replace('_', ' ')}).` : 'No budget given.');
    if (lead.timeline) parts.push(`Timeline: ${lead.timeline}.`);
  }
  if (prompt_injection_detected) parts.push('Message contains instructions aimed at the AI system; treated as untrusted data and not followed.');
  if (duplicate) parts.push(`Matches existing lead ${lead.duplicate_check.duplicate_of} (${lead.duplicate_check.match_type.replace(/_/g, ' ')}).`);
  if (!lead.validation.is_complete) parts.push(`Missing: ${lead.validation.missing_required.join(', ')}.`);

  const presentFields = 13 - Math.min(missing_fields.length, 13);
  let confidence = 0.5 + presentFields * 0.035;
  if (spam && lead.spam_check.spam_score >= 5) confidence = 0.95;
  if (prompt_injection_detected) confidence = Math.min(confidence, 0.6);

  const analysis = {
    lead_category,
    confidence: round2(Math.min(confidence, 0.95)),
    lead_score: suggested,
    lead_temperature: spam ? 'REJECT' : temp,
    qualification_status,
    buying_intent,
    budget_fit,
    urgency,
    authority_level,
    business_need,
    service_fit,
    company_fit,
    business_fit,
    duplicate,
    spam,
    prompt_injection_detected,
    missing_fields,
    pain_points,
    requires_followup: ['HOT', 'WARM', 'COLD'].includes(lead_category),
    recommended_action,
    analysis_summary: parts.join(' '),
  };

  return {
    json: {
      ...lead,
      analysis,
      analysis_meta: { source: 'mock', model: MODEL, generated_at: new Date().toISOString() },
    },
    pairedItem: { item: i },
  };
});

// n8n Code node: "AI · Build Analysis Request"  (mode: Run Once for All Items)
