// n8n Code node: "Parse & Validate Analysis"  (mode: Run Once for All Items)
// Accepts either the DEMO mock analysis or a raw AI provider response (Anthropic Messages API
// or OpenAI-compatible chat completions) and returns ONE validated analysis shape.
// Fail-safe rules:
//   - unparseable / invalid / refused / missing AI output -> analysis_status = "failed" -> NEEDS_REVIEW
//   - the AI may ADD risk flags (spam, injection) but can never REMOVE deterministic ones
//     (duplicate, spam signals, prompt-injection patterns, missing fields).

const ENUMS = {
  lead_category: ['HOT', 'WARM', 'COLD', 'REJECT', 'SPAM', 'DUPLICATE', 'NEEDS_REVIEW'],
  lead_temperature: ['HOT', 'WARM', 'COLD', 'REJECT'],
  qualification_status: ['QUALIFIED', 'NURTURE', 'REJECTED', 'DUPLICATE', 'NEEDS_REVIEW', 'INCOMPLETE'],
  buying_intent: ['high', 'medium', 'low', 'unclear'],
  budget_fit: ['strong', 'moderate', 'weak', 'very_low', 'unknown'],
  urgency: ['high', 'medium', 'low', 'unknown'],
  authority_level: ['decision_maker', 'influencer', 'individual', 'unknown'],
  business_need: ['strong', 'moderate', 'weak'],
  service_fit: ['strong', 'partial', 'none'],
  company_fit: ['strong', 'moderate', 'weak'],
  business_fit: ['strong', 'moderate', 'weak'],
};
const AI_BUILD_NODE = 'AI · Build Analysis Request';

function extractProviderText(resp) {
  if (!resp || typeof resp !== 'object') return { error: 'empty_response' };
  if (resp.error) {
    const msg = typeof resp.error === 'string' ? resp.error : resp.error.message || JSON.stringify(resp.error);
    return { error: `provider_error: ${String(msg).slice(0, 200)}` };
  }
  if (Array.isArray(resp.content)) { // Anthropic Messages API
    if (resp.stop_reason === 'refusal') return { error: 'model_refusal' };
    if (resp.stop_reason === 'max_tokens') return { error: 'truncated_at_max_tokens' };
    return { text: resp.content.filter((b) => b.type === 'text').map((b) => b.text).join('') };
  }
  if (Array.isArray(resp.choices)) { // OpenAI-compatible
    const c = resp.choices[0] || {};
    if (c.finish_reason === 'length') return { error: 'truncated_at_max_tokens' };
    return { text: (c.message && c.message.content) || '' };
  }
  return { error: 'no_ai_response (AI node disabled or returned an unknown shape)' };
}

function parseJson(text) {
  if (!text) throw new Error('empty_text');
  const stripped = text.replace(/```(?:json)?/gi, '').trim();
  const start = stripped.indexOf('{');
  const end = stripped.lastIndexOf('}');
  if (start === -1 || end <= start) throw new Error('no_json_object');
  return JSON.parse(stripped.slice(start, end + 1));
}

function validate(a) {
  const errors = [];
  const v = {};
  for (const [k, allowed] of Object.entries(ENUMS)) {
    const val = typeof a[k] === 'string' ? a[k].trim() : a[k];
    const match = allowed.find((x) => x.toLowerCase() === String(val).toLowerCase());
    if (!match) errors.push(`${k}=${JSON.stringify(a[k])}`);
    v[k] = match || null;
  }
  const conf = Number(a.confidence);
  v.confidence = Number.isFinite(conf) ? Math.max(0, Math.min(1, conf)) : 0;
  const score = Number(a.lead_score);
  v.lead_score = Number.isFinite(score) ? Math.max(0, Math.min(100, Math.round(score))) : null;
  if (v.lead_score === null) errors.push('lead_score');
  v.duplicate = a.duplicate === true;
  v.spam = a.spam === true;
  v.prompt_injection_detected = a.prompt_injection_detected === true;
  v.requires_followup = a.requires_followup === true;
  v.missing_fields = Array.isArray(a.missing_fields) ? a.missing_fields.map(String).slice(0, 20) : [];
  v.pain_points = Array.isArray(a.pain_points) ? a.pain_points.map((p) => String(p).slice(0, 200)).slice(0, 5) : [];
  v.recommended_action = String(a.recommended_action || '').slice(0, 500);
  v.analysis_summary = String(a.analysis_summary || '').slice(0, 1500);
  if (!v.analysis_summary) errors.push('analysis_summary');
  return { analysis: v, errors };
}

function failedAnalysis(lead, reason) {
  return {
    lead_category: 'NEEDS_REVIEW', confidence: 0, lead_score: 0, lead_temperature: 'REJECT',
    qualification_status: 'NEEDS_REVIEW', buying_intent: 'unclear', budget_fit: 'unknown', urgency: 'unknown',
    authority_level: 'unknown', business_need: 'weak', service_fit: 'none', company_fit: 'weak', business_fit: 'weak',
    duplicate: false, spam: false, prompt_injection_detected: false, requires_followup: false,
    missing_fields: [], pain_points: [],
    recommended_action: 'Manual review: automated analysis was not available for this lead.',
    analysis_summary: `Automated analysis failed (${reason}). Raw lead data preserved for manual review.`,
  };
}

return $input.all().map((item, i) => {
  const j = item.json;
  let lead;
  let raw;
  let source;
  let model;
  let error = null;

  if (j.analysis_meta && j.analysis_meta.source === 'mock') {
    ({ analysis: raw, ...lead } = j);
    source = 'mock';
    model = j.analysis_meta.model;
  } else {
    source = 'ai';
    // AI path: this item is the provider response (or the pass-through lead if the HTTP node is disabled).
    let built = null;
    try { built = $(AI_BUILD_NODE).itemMatching(i).json; } catch (e) { built = null; }
    lead = built || (j.lead_id ? j : { lead_id: `UNKNOWN-${i + 1}` });
    model = (lead.config && lead.config.ai_model) || 'unknown';
    const extracted = j.lead_id ? { error: 'no_ai_response (AI node disabled or skipped)' } : extractProviderText(j);
    if (extracted.error) error = extracted.error;
    else {
      try { raw = parseJson(extracted.text); } catch (e) { error = `invalid_json: ${e.message}`; }
    }
  }
  const { ai_request, analysis_meta, ...cleanLead } = lead;

  let analysis;
  if (!error) {
    const res = validate(raw || {});
    if (res.errors.length) error = `schema_invalid: ${res.errors.join(', ')}`;
    else analysis = res.analysis;
  }
  if (error) analysis = failedAnalysis(cleanLead, error);

  // Deterministic facts always win: the AI can add flags, never remove them.
  if (cleanLead.duplicate_check && cleanLead.duplicate_check.is_duplicate) analysis.duplicate = true;
  if (cleanLead.spam_check && cleanLead.spam_check.likely_spam) analysis.spam = true;
  if (cleanLead.security && cleanLead.security.prompt_injection_suspected) analysis.prompt_injection_detected = true;
  if (cleanLead.validation) {
    analysis.missing_fields = [...new Set([...cleanLead.validation.missing_fields, ...analysis.missing_fields])];
  }

  return {
    json: {
      ...cleanLead,
      analysis,
      analysis_meta: {
        source,
        model,
        status: error ? 'failed' : 'ok',
        error,
        validated_at: new Date().toISOString(),
      },
    },
    pairedItem: { item: i },
  };
});

// n8n Code node: "Score Lead"  (mode: Run Once for All Items)
// Hybrid scoring: the AI (or mock) rates each dimension; deterministic rules turn the ratings
// into points, apply penalties, clamp to 0-100, and apply business-rule overrides.
//
//   +20 budget fit · +20 authority · +20 business need · +15 urgency · +15 service fit · +10 company fit
//   -20 unclear intent · -30 very low budget · -50 spam · -100 malicious / prompt injection
//   80-100 HOT · 55-79 WARM · 30-54 COLD · 0-29 REJECT (low value)
//
// Override precedence (first match wins):
//   analysis failed -> NEEDS_REVIEW · security flag -> NEEDS_REVIEW · spam -> SPAM
//   duplicate -> DUPLICATE · incomplete -> NEEDS_REVIEW (INCOMPLETE) · otherwise the score band

const POINTS = {
  budget_fit: { strong: 20, moderate: 12, weak: 5, very_low: 0, unknown: 0 },
  authority_level: { decision_maker: 20, influencer: 12, individual: 5, unknown: 0 },
  business_need: { strong: 20, moderate: 12, weak: 4 },
  urgency: { high: 15, medium: 9, low: 3, unknown: 0 },
  service_fit: { strong: 15, partial: 8, none: 0 },
  company_fit: { strong: 10, moderate: 6, weak: 2 },
};
const PENALTIES = { unclear_intent: -20, very_low_budget: -30, spam: -50, malicious_input: -100 };

// Used when the rules disagree with the AI's suggested category (the rules win).
const RULE_ACTIONS = {
  HOT: 'Contact within 30 minutes and offer a discovery call.',
  WARM: 'Send a personal follow-up today with 2-3 scoping questions.',
  COLD: 'Add to the nurture sequence and re-score on engagement.',
  REJECT: 'Archive; low fit and low intent.',
  SPAM: 'Archive as spam. Do not reply.',
  DUPLICATE: 'Merge into the existing record and notify its owner.',
  NEEDS_REVIEW: 'Manual review required before any follow-up.',
};

return $input.all().map((item, i) => {
  const lead = item.json;
  const a = lead.analysis;
  const cfg = lead.config || {};
  const HOT = cfg.score_hot_min ?? 80;
  const WARM = cfg.score_warm_min ?? 55;
  const COLD = cfg.score_cold_min ?? 30;

  const breakdown = [];
  const components = {};
  let score = 0;
  for (const [dim, table] of Object.entries(POINTS)) {
    const pts = table[a[dim]] ?? 0;
    components[dim] = pts;
    score += pts;
    breakdown.push(`+${pts} ${dim.replace(/_/g, ' ')} (${a[dim]})`);
  }
  const penalties = [];
  if (a.buying_intent === 'unclear') penalties.push(['unclear intent', PENALTIES.unclear_intent]);
  if (a.budget_fit === 'very_low') penalties.push(['very low budget', PENALTIES.very_low_budget]);
  if (a.spam) penalties.push(['spam', PENALTIES.spam]);
  if (a.prompt_injection_detected || (lead.security && lead.security.markup_detected)) penalties.push(['malicious / injection attempt', PENALTIES.malicious_input]);
  for (const [label, pts] of penalties) {
    score += pts;
    breakdown.push(`${pts} ${label}`);
  }
  const rawScore = score;
  score = Math.max(0, Math.min(100, score));

  const lead_temperature = a.spam ? 'REJECT' : score >= HOT ? 'HOT' : score >= WARM ? 'WARM' : score >= COLD ? 'COLD' : 'REJECT';

  let lead_category = lead_temperature;
  let qualification_status = { HOT: 'QUALIFIED', WARM: 'QUALIFIED', COLD: 'NURTURE', REJECT: 'REJECTED' }[lead_temperature];
  let override_reason = null;
  const isComplete = lead.validation ? lead.validation.is_complete : true;

  if (lead.analysis_meta.status === 'failed') {
    lead_category = 'NEEDS_REVIEW'; qualification_status = 'NEEDS_REVIEW';
    override_reason = `analysis failed: ${lead.analysis_meta.error}`;
  } else if (a.prompt_injection_detected || (lead.security && lead.security.risk_level === 'high')) {
    lead_category = 'NEEDS_REVIEW'; qualification_status = 'NEEDS_REVIEW';
    override_reason = `security: ${(lead.security && lead.security.flags.join(', ')) || 'prompt injection detected by AI'}`;
  } else if (a.spam) {
    lead_category = 'SPAM'; qualification_status = 'REJECTED';
    override_reason = 'spam signals';
  } else if (a.duplicate) {
    lead_category = 'DUPLICATE'; qualification_status = 'DUPLICATE';
    override_reason = `duplicate of ${lead.duplicate_check.duplicate_of} (${lead.duplicate_check.match_type})`;
  } else if (!isComplete) {
    lead_category = 'NEEDS_REVIEW'; qualification_status = 'INCOMPLETE';
    override_reason = `incomplete: missing ${lead.validation.missing_required.join(', ')}`;
  }
  if (override_reason) breakdown.push(`override → ${lead_category} (${override_reason})`);

  const aiAgrees = a.lead_category === lead_category;
  const recommended_action = aiAgrees && a.recommended_action
    ? a.recommended_action
    : `${RULE_ACTIONS[lead_category]}${override_reason && lead_category === 'NEEDS_REVIEW' ? ` Reason: ${override_reason}.` : ''}`;

  return {
    json: {
      ...lead,
      lead_score: score,
      lead_temperature,
      lead_category,
      qualification_status,
      requires_followup: ['HOT', 'WARM', 'COLD'].includes(lead_category) && lead.email_valid === true,
      override_reason,
      recommended_action,
      scoring: {
        rule_score_before_clamp: rawScore,
        components,
        penalties: Object.fromEntries(penalties),
        breakdown,
        thresholds: { hot: HOT, warm: WARM, cold: COLD },
        ai_suggested_score: a.lead_score,
        ai_suggested_category: a.lead_category,
        ai_agrees_with_rules: aiAgrees,
      },
    },
    pairedItem: { item: i },
  };
});

// n8n Code node: "DEMO · Mock Follow-up"  (mode: Run Once for All Items)
// DEMO MODE ONLY. Drafts a professional follow-up email from the lead's own context
